import React, { useState } from "react";
import { Link } from "react-router-dom";

function NavBar() {
      
  const planets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <nav className=" text-white  h-12">
        <div className="header justify-between flex">
            <Link to="/" className=" text-3xl">Solar System</Link>
            <div className=""><img width="25" height="25" src="https://img.icons8.com/ios/50/menu--v1.png" alt="menu--v1"/></div>
        </div>
    </nav>
  )
}


export default NavBar;
